// Check if ortho file exists at expected location
// In n8n, file system access requires Execute Command node.
// This Set node prepares variables for the existence check.
const missionId = $('Trigger — Mission Webhook').item.json.body.mission_id;
const outputPath = $input.item.json[0]?.output_path || '';
const orthoPath = outputPath + '\\mapping\\orthomosaic.tif';

// Track poll attempt (stored in workflow static data)
const staticData = $getWorkflowStaticData('global');
staticData.pollAttempt = (staticData.pollAttempt || 0) + 1;

return [
  {
    json: {
      mission_id: missionId,
      output_path: outputPath,
      ortho_path: orthoPath,
      poll_attempt: staticData.pollAttempt,
      max_attempts: 30
    }
  }
];

