// Parse review decisions from operator webhook
const body = $input.item.json.body || {};
const decisions = body.decisions || [];
const missionId = body.mission_id || $('E4 — Parse Result').first().json.mission_id;

// Separate decisions by action
const excluded = decisions.filter(d => d.action === 'exclude').map(d => d.detection_id);
const flagged = decisions.filter(d => d.action === 'flag').map(d => d.detection_id);
const approved = decisions.filter(d => d.action === 'approve').map(d => d.detection_id);

return [
  {
    json: {
      mission_id: missionId,
      excluded_ids: excluded,
      flagged_ids: flagged,
      approved_ids: approved,
      has_exclusions: excluded.length > 0,
      decisions_count: decisions.length,
      // Pass through E4 file paths for potential re-run
      pdf_path: $('E4 — Parse Result').first().json.pdf_path,
      species_map_path: $('E4 — Parse Result').first().json.species_map_path,
      health_map_path: $('E4 — Parse Result').first().json.health_map_path,
      geojson_path: $('E4 — Parse Result').first().json.geojson_path,
      ortho_path: $('E0 — Build Ortho Path').first().json.ortho_path,
      processing_job_id: $('E0 — Check Mission').first().json[0].processing_job_id
    }
  }
];
